function cfRoot(c){return c._root||c}
function cfKey(c){return (c._root?c.id.slice(c._root.id.length):'primary')+':'+c.klass+':'+subclassKey(c)}
function cfState(c){const all=cfRoot(c).classChoiceData||{};return all[cfKey(c)]||all[c.id+':'+c.klass+':'+subclassKey(c)]||{picks:{},history:{},assignments:{}}}
function cfPicks(c,key,state=cfState(c)){return state.picks?.[key]||[]}
function cfSelected(c,id){return Object.values(cfState(c).picks||{}).some(a=>Array.isArray(a)&&a.includes(id))}
function cfPrereq(c,o,state=cfState(c)){
 if(!o.prerequisite?.length)return '';
 const check=p=>{const errors=[];if(p.level){const lv=typeof p.level==='number'?p.level:p.level.level;if((c.level||1)<lv)errors.push('Class level '+lv)}if(p.pact&&!cfPicks(c,'pact',state).includes('pact-of-the-'+p.pact.toLowerCase()))errors.push('Pact of the '+p.pact);if(p.spell){for(const v of p.spell){if(v==='hex/curse#x'){if(!(c.spells||[]).includes('hex')&&subclassKey(c)!=='warlock:hexblade'&&!cfPicks(c,'invocations',state).includes('sign-of-ill-omen'))errors.push('Hex or a curse feature')}else {const id=cfSlug(v.split('#')[0].split('|')[0]);if(!(c.spells||[]).includes(id))errors.push('Know '+v.split('#')[0])}}}return errors.join('; ')};
 const errs=o.prerequisite.map(check);return errs.includes('')?'':errs.join(' OR ')
}
function cfCatalog(type){return CF_OPTIONS.filter(o=>o.types?.includes(type))}
function cfSpells(filter){return allSpells().filter(filter).map(s=>({id:s.index,name:s.name+' · '+(s.level?'Level '+s.level:'Cantrip'),text:(s.desc||[]).join('\n'),source:'Spell catalog'})).sort((a,b)=>a.name.localeCompare(b.name))}
