 if(sub==='wizard:bladesinging'&&lv>=2)add('bladesinger-weapon','Training in War and Song weapon',1,allItems().filter(x=>x.weapon_range==='Melee'&&!x.properties?.some(p=>p.index==='two-handed')).map(x=>({id:x.index,name:x.name,text:'One type of one-handed melee weapon.'})),'Weapon proficiency.');
