function cfTools(){return ['Alchemist’s supplies','Brewer’s supplies','Calligrapher’s supplies','Carpenter’s tools','Cartographer’s tools','Cobbler’s tools','Cook’s utensils','Glassblower’s tools','Jeweler’s tools','Leatherworker’s tools','Mason’s tools','Painter’s supplies','Potter’s tools','Smith’s tools','Tinker’s tools','Weaver’s tools','Woodcarver’s tools'].map(x=>cfOpt(x))}
